    check_if_content_has_link(message_content) {
      const me2 = this;
      const parser = new DOMParser();
      const doc = parser.parseFromString(message_content, "text/html");
      const paragraphs = doc.querySelectorAll("p");
      paragraphs.forEach((p) => {
        const urlRegex = new RegExp("((https?:\\/\\/|www\\.|(?<![\\w-])[\\w-]+\\.)[-\\w.]+(:\\d+)?(\\/([\\w/_\\-.%]*(\\?\\S+)?)?)?)", "gi");
        let link = "";
        Array.from(p.childNodes).forEach((node) => {
          if (node.nodeType === Node.TEXT_NODE) {
            const replacedText = node.textContent.replace(
              urlRegex,
              function(matched) {
                me2.is_link = 1;
                if (!(matched.includes("http") || matched.includes("https"))) {
                  link = "https://";
                }
                return '<a href="' + link + matched + '" target="_blank" style="color:#027eb5">' + matched + "</a>";
              }
            );
            const fragment = document.createRange().createContextualFragment(replacedText);
            p.replaceChild(fragment, node);
          }
        });
      });
      return doc.body.innerHTML;
    }
    check_if_content_has_email(message_content) {
      const me2 = this;
      const parser = new DOMParser();
      const doc = parser.parseFromString(message_content, "text/html");
      const paragraphs = doc.querySelectorAll("p");
      paragraphs.forEach((p) => {
        const mailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/;
        Array.from(p.childNodes).forEach((node) => {
          if (node.nodeType === Node.TEXT_NODE) {
            const replacedText = node.textContent.replace(
              mailRegex,
              function(matched) {
                me2.is_link = 1;
                return '<a href="mailto:' + matched + '" target="_blank" style="color:#027eb5">' + matched + "</a>";
              }
            );
            const fragment = document.createRange().createContextualFragment(replacedText);
            p.replaceChild(fragment, node);
          }
        });
      });
      return doc.body.innerHTML;
    }
